<?php
ob_start();session_id('nstBankControl'.bin2hex(random_bytes(8)));session_start();$cookie='PHPSESSID='.session_id();session_write_close();
function controlCall($route,$cookie,$post=null){$c=curl_init('http://localhost'.$route);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>$cookie,CURLOPT_TIMEOUT=>10]);if($post!==null)curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($post),CURLOPT_HTTPHEADER=>['Content-Type: application/json']]);$body=curl_exec($c);$code=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);return [$code,$body];}
try{session_start();$_SESSION['user']='admin-prueba';session_write_close();foreach(['/api/index.php/bancos/saldos','/api/index.php/bancos/saldos/historial?cuenta=2','/views/SaldosBancos.php'] as $route){list($code) = controlCall($route,$cookie);if($code!==403)throw new Exception('Non-superadmin access '.$code);}list($code)=controlCall('/api/index.php/bancos/saldos',$cookie,[]);if($code!==403)throw new Exception('Non-superadmin POST access');
session_start();$_SESSION['user']='superadmin';session_write_close();list($code,$body)=controlCall('/api/index.php/bancos/saldos',$cookie);$data=json_decode($body,true);if($code!==200||empty($data['csrf'])||count($data['Cuentas'])!==2)throw new Exception('Control GET failed');list($code)=controlCall('/api/index.php/bancos/saldos',$cookie,[]);if($code!==403)throw new Exception('CSRF protection failed');list($code)=controlCall('/api/index.php/bancos/saldos',$cookie,['_csrf'=>$data['csrf'],'IdCuenta'=>1]);if($code!==422)throw new Exception('Invalid bank accepted');echo 'Live control GET verified; non-superadmin page/GET/POST denied; CSRF and invalid bank protected. No balances changed.'.PHP_EOL;
}finally{session_start();$_SESSION=[];session_destroy();ob_end_flush();}
